var n=`0500-rashouf`;var t=`world-0500`;var o=`JO`;var r=`western-asia`;var a=4;var s=102;var l={en:`Rashouf`,ua:`Рашуф`};var g={en:`A traditional dish from Jordan, centered on green lentils, bulgur, plain yogurt, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Йорданія. Основні складники: зелена сочевиця, булгур, натуральний йогурт, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 85 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 85 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:85,i:[[`green-lentils`,220,`g`],[`water`,1100,`ml`],[`bulgur`,150,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`plain-yogurt`,420,`g`],[`garlic`,3,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`yellow-onion`,160,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`mint`,12,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var u={slug:n,id:t,country:`JO`,region:r,servings:4,minutes:102,title:l,text:g,steps:d};export{o as country,u as default,t as id,s as minutes,r as region,a as servings,n as slug,d as steps,g as text,l as title};